// Package events is the cross-service event SSoT. It carries the wire types
// for Pub/Sub events that fan out across service boundaries (scenario → account
// / card / gateway, shop → account / gateway, ...).
//
// Ownership rule: events with a single publisher should live in that
// publisher's api-<svc> package. Events with multiple publishers — or events
// that are conceptually cross-cutting (like "faction selected", which is
// emitted by both scenario and shop) — belong here so there is exactly one
// source of truth for the schema.
//
// All subscribers MUST use the idempotency pattern: insert EventID into a
// `<schema>.processed_events` table at the start of the handler transaction,
// treat a duplicate-key hit as an idempotent ack, and only perform the side
// effect if the insert succeeded. See docs/architecture/ARCHITECTURE.md
// §Cross-service events.
package pubsubevents

import "time"

// Topic names (per env — the actual GCP Pub/Sub topic ID is just the name;
// environments are separated at the project level, so the names are stable
// across dev / stg / prod).
const (
	TopicFactionSelected = "faction-selected"
	TopicPremiumUpdated  = "premium-updated"
)

// Subscription names. Each subscriber service owns one subscription per topic;
// the `{topic}-{subscriber}-sub` convention keeps them grep-able.
const (
	SubFactionSelectedAccount = "faction-selected-account-sub"
	SubFactionSelectedCard    = "faction-selected-card-sub"
	SubFactionSelectedGateway = "faction-selected-gateway-sub"

	SubPremiumUpdatedAccount = "premium-updated-account-sub"
	SubPremiumUpdatedGateway = "premium-updated-gateway-sub"
)

// DLQ topic names. Pub/Sub service agent publishes to these when a subscriber
// repeatedly nacks the same message — see infra/modules/pubsub for the IAM.
const (
	DLQFactionSelected = "faction-selected-dlq"
	DLQPremiumUpdated  = "premium-updated-dlq"
)

// Event type discriminators. These are intentionally stable strings rather
// than Pub/Sub attribute enums so the payload is self-describing when
// inspected in logs or DLQ dumps.
const (
	EventTypeFactionSelected = "faction_selected"
	EventTypePremiumUpdated  = "premium_updated"
)

// FactionSelectedSource enumerates the publishers of FactionSelectedEvent.
// The account subscriber maps these to the `player_factions.source` column
// (initial_selection / shop_purchase).
const (
	FactionSourceScenarioInitial = "scenario_initial"
	FactionSourceShopPurchase    = "shop_purchase"
)

// FactionSelectedEvent is published when a player's faction ownership changes
// (either initial tutorial selection or a shop purchase). Subscribers:
//
//   - account: INSERTs player_factions + UPDATEs players.selected_faction
//     (the latter only for scenario_initial).
//   - card:    writes player_cards (initial pack = faction + Neutral;
//     shop purchase = faction only; subscriber decides from Source).
//   - gateway: pushes a WS `faction_selection_complete` message to the
//     player's active connection.
//
// Idempotency: subscribers MUST dedupe on EventID via their
// `processed_events` table (see package doc).
type FactionSelectedEvent struct {
	// EventType is always EventTypeFactionSelected. Included in the payload
	// so a single subscriber can safely handle more than one event type on
	// the same topic if that ever happens.
	EventType string `json:"event_type"`

	// EventID is a UUIDv4 generated by the publisher. It is the idempotency
	// key — subscribers dedupe on this column.
	EventID string `json:"event_id"`

	// Timestamp is the publisher's wall clock at publish time.
	Timestamp time.Time `json:"timestamp"`

	// PlayerID is the target of the update.
	PlayerID string `json:"player_id"`

	// Faction is one of the SelectableFactions
	// ("SHE" / "Tenki" / "Sugar" / "Tuners"). Neutral is never published —
	// neutral cards are granted implicitly alongside the initial pack.
	Faction string `json:"faction"`

	// Source is one of FactionSourceScenarioInitial / FactionSourceShopPurchase.
	// Subscribers key on this to decide whether to grant the Neutral pack
	// and whether to update players.selected_faction.
	Source string `json:"source"`
}

// PremiumUpdatedEvent is published by shop when a subscription state change
// results in a new is_premium value for a player. Subscribers:
//
//   - account: UPDATEs players.is_premium + players.premium_expires_at.
//   - gateway: pushes a WS `premium_update_complete` message to the player.
//
// Source is always FactionSourceShopPurchase-equivalent ("shop"); it exists
// as a field so future admin-override publishers can reuse the same schema.
type PremiumUpdatedEvent struct {
	EventType        string     `json:"event_type"`
	EventID          string     `json:"event_id"`
	Timestamp        time.Time  `json:"timestamp"`
	PlayerID         string     `json:"player_id"`
	IsPremium        bool       `json:"is_premium"`
	PremiumExpiresAt *time.Time `json:"premium_expires_at,omitempty"`
	Source           string     `json:"source"`
}

// PremiumUpdatedSourceShop is the canonical Source value emitted by shop.
const PremiumUpdatedSourceShop = "shop"
